  check(v2?Array.isArray(plan.priorArtifacts)&&plan.priorArtifacts.length<=512:!Object.hasOwn(plan,'priorArtifacts'),'versioned prior artifact declaration');
  const selected=v2?plan.priorArtifacts:[],seen=new Set();
